<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}">
<title>Haman Planner</title>
<style>
:root{--ink:#172033;--muted:#718096;--line:#e4e8ef;--bg:#f5f7fa;--card:#fff;--nav:#101827;--nav2:#1d2a3e;--ok:#0f9d72;--warn:#c98513;--danger:#c24141;--blue:#3157d5}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
button,input,select,textarea{font:inherit}button{cursor:pointer}.shell{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}.side{background:var(--nav);color:#fff;padding:22px 16px;position:sticky;top:0;height:100vh;overflow:auto}.brand{font-weight:850;font-size:21px;padding:8px 10px 25px}.brand small{display:block;color:#8e9ab0;font-size:11px;font-weight:500;margin-top:5px}.nav{display:grid;gap:4px}.nav button{border:0;background:transparent;color:#b9c4d4;text-align:right;padding:11px 12px;border-radius:10px}.nav button:hover,.nav button.active{background:var(--nav2);color:#fff}.nav .group{color:#65738a;font-size:11px;margin:18px 10px 4px}.side-bottom{margin-top:25px;border-top:1px solid #253146;padding-top:15px}.side-bottom button{width:100%;background:transparent;border:0;color:#9eabc0;text-align:right;padding:9px 12px}.main{min-width:0;padding:28px 32px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.eyebrow{font-size:12px;color:var(--muted);margin-bottom:5px}.title{font-size:29px;font-weight:850;letter-spacing:-.7px}.top-actions{display:flex;gap:8px}.btn{border:1px solid #d5dbe4;background:#fff;color:var(--ink);border-radius:10px;padding:10px 14px;font-weight:700}.btn:hover{border-color:#aeb8c8}.btn.primary{background:var(--ink);border-color:var(--ink);color:#fff}.btn.danger{color:#b42318;border-color:#f0c6c2}.btn.small{padding:7px 10px;font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 3px 15px rgba(16,24,39,.035)}.metric{font-size:28px;font-weight:850;margin:6px 0}.muted{color:var(--muted);font-size:13px}.section{margin-top:18px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}.section-head h2{font-size:17px;margin:0}.two{display:grid;grid-template-columns:1.45fr 1fr;gap:14px}.list{display:grid;gap:8px}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;border:1px solid var(--line);border-radius:11px;padding:12px;background:#fff}.row-main{min-width:0}.row-title{font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row-sub{font-size:12px;color:var(--muted);margin-top:4px}.row-actions{display:flex;gap:5px;flex-shrink:0}.pill{font-size:11px;padding:4px 8px;border-radius:999px;background:#edf1f6;white-space:nowrap}.pill.ok{background:#e9f8f2;color:#087f5b}.pill.warn{background:#fff6df;color:#9a6509}.pill.danger{background:#fff0ef;color:#a52b20}.empty{text-align:center;padding:35px;color:#8b97a8}.progress{height:7px;background:#edf0f4;border-radius:99px;overflow:hidden;margin-top:9px}.progress span{display:block;height:100%;background:var(--ink)}.toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:12px}.search{width:min(360px,100%);padding:10px 12px;border:1px solid #d5dbe4;background:#fff;border-radius:10px}.filters{display:flex;gap:8px;flex-wrap:wrap}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:11px;border-bottom:1px solid var(--line);text-align:right;font-size:13px}.table th{font-size:11px;color:var(--muted);font-weight:700}.modal-back{position:fixed;inset:0;background:rgba(15,23,42,.48);display:none;align-items:center;justify-content:center;padding:20px;z-index:50}.modal-back.show{display:flex}.modal{width:min(720px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:23px}.modal h2{margin:0 0 18px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field.full{grid-column:1/-1}.field label{display:block;font-size:12px;font-weight:750;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;border:1px solid #d7dce5;border-radius:10px;padding:10px 11px;background:#fff;outline:0}.field textarea{min-height:95px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:#7b8799;box-shadow:0 0 0 3px #eef1f5}.modal-actions{display:flex;justify-content:flex-start;gap:8px;margin-top:18px}.toast{position:fixed;left:22px;bottom:22px;background:#172033;color:#fff;padding:12px 15px;border-radius:10px;display:none;z-index:100;box-shadow:0 15px 35px rgba(0,0,0,.2)}.toast.show{display:block}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}.day{background:#fff;border:1px solid var(--line);border-radius:12px;min-height:140px;padding:10px}.day strong{font-size:12px}.block{margin-top:7px;padding:7px;border-radius:8px;background:#eef2ff;font-size:11px}.danger-text{color:var(--danger)}.stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.hide{display:none!important}@media(max-width:1050px){.shell{grid-template-columns:80px 1fr}.brand span,.brand small,.nav .label,.nav .group,.side-bottom .label{display:none}.brand{text-align:center}.nav button,.side-bottom button{text-align:center}.main{padding:22px}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.shell{display:block}.side{height:auto;position:sticky;z-index:20;padding:8px;display:flex;overflow:auto}.brand{padding:10px}.nav{display:flex;gap:4px}.nav .group,.side-bottom{display:none}.nav button{white-space:nowrap}.main{padding:16px}.top{flex-direction:column}.cards,.two,.form-grid,.stat-grid{grid-template-columns:1fr}.calendar{grid-template-columns:1fr 1fr}.day{min-height:100px}}
</style>
</head>
<body>
<div class="shell">
<aside class="side">
<div class="brand"><span>Haman Planner</span><small>Personal & Business Operating System</small></div>
<nav class="nav">
<button class="active" data-view="today">◉ <span class="label">امروز</span></button>
<button data-view="inbox">▣ <span class="label">Inbox</span></button>
<div class="group">مدیریت</div>
<button data-view="tasks">✓ <span class="label">کارها</span></button>
<button data-view="goals">◎ <span class="label">اهداف</span></button>
<button data-view="projects">▤ <span class="label">پروژه‌ها</span></button>
<button data-view="areas">◈ <span class="label">حوزه‌ها</span></button>
<button data-view="milestones">◇ <span class="label">Milestones</span></button>
<div class="group">اجرا</div>
<button data-view="calendar">□ <span class="label">تقویم و برنامه</span></button>
<button data-view="execution">◷ <span class="label">Execution</span></button>
<button data-view="reminders">◌ <span class="label">یادآورها</span></button>
<div class="group">بازنگری</div>
<button data-view="reviews">↻ <span class="label">Reviews</span></button>
<button data-view="analytics">◫ <span class="label">Analytics</span></button>
<button data-view="notes">▤ <span class="label">یادداشت‌ها</span></button>
<button data-view="decisions">◆ <span class="label">تصمیم‌ها</span></button>
</nav>
<div class="side-bottom">
<button onclick="location.href='{{route('account.settings')}}'">⚙ <span class="label">امنیت حساب</span></button>
<form method="post" action="{{route('logout')}}">@csrf<button type="submit">↪ <span class="label">خروج</span></button></form>
</div>
</aside>
<main class="main">
<div class="top"><div><div class="eyebrow">Haman Planner · {{auth()->user()->name}}</div><div class="title" id="title">امروز</div></div><div class="top-actions"><button class="btn" onclick="refreshView()">↻ بروزرسانی</button><button class="btn primary" onclick="openCreate()">＋ افزودن</button></div></div>
<div id="content"></div>
</main></div>

<div class="modal-back" id="modal"><div class="modal"><h2 id="modalTitle">افزودن</h2><div id="modalBody"></div></div></div>
<div class="toast" id="toast"></div>

<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;
let view='today', cache={areas:[],goals:[],projects:[],milestones:[],tasks:[]};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmtDate=v=>v?new Date(v).toLocaleDateString('fa-IR'): '—';
const fmtDateTime=v=>v?new Date(v).toLocaleString('fa-IR',{dateStyle:'short',timeStyle:'short'}):'—';
const toast=(m)=>{const e=$('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
async function api(path,opt={}){const method=(opt.method||'GET').toUpperCase();const h={'Accept':'application/json','X-CSRF-TOKEN':csrf,...(opt.headers||{})};if(method!=='GET'&&method!=='HEAD')h['Content-Type']='application/json';const r=await fetch('/api'+path,{credentials:'same-origin',...opt,headers:h});if(r.status===401){location.href='/login';throw Error('401')}if(r.status===419){toast('نشست شما منقضی شده؛ صفحه را تازه کنید.');throw Error('419')}if(!r.ok){let x={};try{x=await r.json()}catch{};throw Error(x.message||Object.values(x.errors||{}).flat().join(' ')||('HTTP '+r.status))}return r.status===204?null:r.json()}
async function loadCache(){const [a,g,p,m,t]=await Promise.all([api('/areas'),api('/goals'),api('/projects'),api('/milestones'),api('/tasks?per_page=100')]);cache.areas=a.data||a;cache.goals=g.data||g;cache.projects=p.data||p;cache.milestones=m.data||m;cache.tasks=t.data||t}
function pill(v){const s=String(v||'active').toLowerCase();let c='';if(['completed','done','on track'].includes(s))c='ok';else if(['blocked','behind','cancelled'].includes(s))c='danger';else if(['waiting','at risk','deferred'].includes(s))c='warn';return '<span class="pill '+c+'">'+esc(v||'active')+'</span>'}
function row(item,kind){const title=item.title||item.name||item.type||'بدون عنوان';const progress=item.progress??null;return '<div class="row"><div class="row-main"><div class="row-title">'+esc(title)+'</div><div class="row-sub">'+(item.deadline?'مهلت: '+fmtDate(item.deadline):item.target_date?'هدف: '+fmtDate(item.target_date):item.description?esc(item.description).slice(0,100):'')+'</div>'+(progress!==null?'<div class="progress"><span style="width:'+Math.max(0,Math.min(100,Number(progress)))+'%"></span></div>':'')+'</div><div class="row-actions">'+pill(item.status||item.health||item.priority)+'<button class="btn small" onclick="editItem('+item.id+',\''+kind+'\')">ویرایش</button><button class="btn small danger" onclick="removeItem('+item.id+',\''+kind+'\')">حذف</button></div></div>'}
async function renderToday(){const [p,a]=await Promise.all([api('/planner/today'),api('/planner/analytics')]);const tasks=p.tasks||p.data||[];const m=a.metrics||a;$('content').innerHTML='<div class="cards">'+[['کارهای امروز',tasks.length],['دقیقه برنامه‌ریزی',m.planned_minutes??0],['دقیقه اجرا',m.actual_minutes??m.completed_minutes??0],['نرخ تکمیل',((m.completion_rate??0)*100).toFixed(0)+'%']].map(x=>'<div class="card"><div class="muted">'+x[0]+'</div><div class="metric">'+x[1]+'</div></div>').join('')+'</div><div class="section two"><div class="card"><div class="section-head"><h2>برنامه امروز</h2><button class="btn small" onclick="openCreate(\'task\')">＋ کار</button></div><div class="list">'+(tasks.length?tasks.slice(0,30).map(t=>row(t,'task')).join(''):'<div class="empty">برای امروز کاری ثبت نشده.</div>')+'</div></div><div class="card"><div class="section-head"><h2>سلامت سیستم</h2><button class="btn small" onclick="openView(\'analytics\')">جزئیات</button></div><div class="stat-grid">'+Object.entries(m).slice(0,6).map(([k,v])=>'<div><div class="muted">'+esc(k.replaceAll('_',' '))+'</div><strong>'+esc(typeof v==='number'?v.toLocaleString():v)+'</strong></div>').join('')+'</div></div></div>'}
async function renderList(kind,label,endpoint=kind){let r=await api('/'+endpoint+(kind==='tasks'?'?per_page=100':''));let rows=r.data||r; if(!Array.isArray(rows))rows=[];cache[kind]=rows;$('content').innerHTML='<div class="card"><div class="toolbar"><input class="search" placeholder="جستجو..." oninput="filterRows(this.value)"><button class="btn primary" onclick="openCreate(\''+kind.slice(0,-1)+'\')">＋ '+label+'</button></div><div class="list" id="rows">'+(rows.length?rows.map(x=>row(x,kind.slice(0,-1))).join(''):'<div class="empty">هنوز موردی ثبت نشده است.</div>')+'</div></div>'}
function filterRows(q){const needle=q.toLowerCase();document.querySelectorAll('#rows .row').forEach(e=>e.style.display=e.textContent.toLowerCase().includes(needle)?'flex':'none')}
async function renderAnalytics(){const a=await api('/planner/analytics');const m=a.metrics||a;$('content').innerHTML='<div class="cards">'+Object.entries(m).map(([k,v])=>'<div class="card"><div class="muted">'+esc(k.replaceAll('_',' '))+'</div><div class="metric">'+esc(typeof v==='number'?v.toLocaleString():v??'—')+'</div></div>').join('')+'</div>'}
async function renderReviews(){const r=await api('/reviews');const rows=r.data||[];$('content').innerHTML='<div class="card"><div class="section-head"><h2>بازنگری‌ها</h2><button class="btn primary" onclick="generateReview()">＋ تولید Review</button></div><div class="list">'+(rows.length?rows.map(x=>'<div class="row"><div><div class="row-title">'+esc(x.type)+'</div><div class="row-sub">'+fmtDate(x.period_start)+' تا '+fmtDate(x.period_end)+' · '+esc(x.summary||'بدون خلاصه')+'</div></div></div>').join(''):'<div class="empty">Review ثبت نشده.</div>')+'</div></div>'}
async function renderNotes(){let r=await api('/notes');let rows=r.data||r;$('content').innerHTML='<div class="card"><div class="section-head"><h2>یادداشت‌ها</h2><button class="btn primary" onclick="openCreate(\'note\')">＋ یادداشت</button></div><div class="list">'+(rows.length?rows.map(x=>row(x,'note')).join(''):'<div class="empty">یادداشتی نیست.</div>')+'</div></div>'}
async function renderDecisions(){let r=await api('/decisions');let rows=r.data||r;$('content').innerHTML='<div class="card"><div class="section-head"><h2>تصمیم‌ها</h2><button class="btn primary" onclick="openCreate(\'decision\')">＋ تصمیم</button></div><div class="list">'+(rows.length?rows.map(x=>row(x,'decision')).join(''):'<div class="empty">تصمیمی ثبت نشده.</div>')+'</div></div>'}
async function renderReminders(){let r=await api('/reminders');let rows=r.data||r;$('content').innerHTML='<div class="card"><div class="section-head"><h2>یادآورها</h2><button class="btn primary" onclick="openCreate(\'reminder\')">＋ یادآور</button></div><div class="list">'+(rows.length?rows.map(x=>row({id:x.id,title:x.task?.title||'Reminder',status:x.status,deadline:x.scheduled_at},'reminder')).join(''):'<div class="empty">یادآوری ثبت نشده.</div>')+'</div></div>'}
async function renderExecution(){let r=await api('/tasks?per_page=100');let rows=r.data||[];$('content').innerHTML='<div class="card"><div class="section-head"><h2>ثبت اجرای کار</h2></div><div class="list">'+(rows.length?rows.map(t=>'<div class="row"><div><div class="row-title">'+esc(t.title)+'</div><div class="row-sub">واقعی: '+(t.actual_minutes||0)+' دقیقه</div></div><button class="btn small" onclick="openExecution('+t.id+')">ثبت اجرا</button></div>').join(''):'<div class="empty">کاری موجود نیست.</div>')+'</div></div>'}
async function renderCalendar(){const d=new Date();const start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));const days=[];for(let i=0;i<7;i++){const x=new Date(start);x.setDate(start.getDate()+i);days.push(x)}const blocks=[];for(const x of days){try{const r=await api('/schedule-blocks?date='+x.toISOString().slice(0,10));blocks.push(r.data||[])}catch{blocks.push([])}}$('content').innerHTML='<div class="card"><div class="section-head"><h2>تقویم این هفته</h2><button class="btn primary" onclick="openCreate(\'schedule\')">＋ بلوک زمانی</button></div><div class="calendar">'+days.map((d,i)=>'<div class="day"><strong>'+d.toLocaleDateString('fa-IR',{weekday:'short',day:'numeric',month:'short'})+'</strong>'+(blocks[i].length?blocks[i].map(b=>'<div class="block">'+fmtDateTime(b.starts_at)+'<br>'+esc(b.task?.title||'Focus block')+'</div>').join(''):'<div class="empty">—</div>')+'</div>').join('')+'</div></div>'}
function openView(v){document.querySelector('[data-view="'+v+'"]').click()}
function refreshView(){loadView(view)}
async function loadView(v='today'){view=v;$('title').textContent=({today:'امروز',inbox:'Inbox',tasks:'کارها',goals:'اهداف',projects:'پروژه‌ها',areas:'حوزه‌ها',milestones:'Milestones',calendar:'تقویم و برنامه',execution:'Execution',reminders:'یادآورها',reviews:'Reviews',analytics:'Analytics',notes:'یادداشت‌ها',decisions:'تصمیم‌ها'})[v]||v;try{if(v==='today'||v==='inbox')await renderToday();else if(v==='analytics')await renderAnalytics();else if(v==='reviews')await renderReviews();else if(v==='notes')await renderNotes();else if(v==='decisions')await renderDecisions();else if(v==='reminders')await renderReminders();else if(v==='execution')await renderExecution();else if(v==='calendar')await renderCalendar();else {const map={tasks:'کارها',goals:'اهداف',projects:'پروژه‌ها',areas:'حوزه‌ها',milestones:'Milestones'};await renderList(v,map[v])}}catch(e){$('content').innerHTML='<div class="card"><div class="danger-text">'+esc(e.message)+'</div></div>'}}
document.querySelectorAll('.nav button[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');loadView(b.dataset.view)});
const schemas={
area:{title:'حوزه',endpoint:'areas',fields:[['name','نام','text',1],['type','نوع','text',0],['status','وضعیت','text',0],['sort_order','ترتیب','number',0],['description','توضیحات','textarea',0]]},
goal:{title:'هدف',endpoint:'goals',fields:[['title','عنوان','text',1],['area_id','حوزه','selectArea',0],['status','وضعیت','text',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['start_date','شروع','date',0],['target_date','موعد','date',0],['success_criteria','معیار موفقیت','textarea',0],['description','توضیحات','textarea',0]]},
project:{title:'پروژه',endpoint:'projects',fields:[['title','عنوان','text',1],['goal_id','هدف','selectGoal',0],['status','وضعیت','text',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['estimated_minutes','زمان برآوردی','number',0],['start_date','شروع','date',0],['target_date','موعد','date',0],['description','توضیحات','textarea',0]]},
milestone:{title:'Milestone',endpoint:'milestones',fields:[['title','عنوان','text',1],['project_id','پروژه','selectProject',1],['status','وضعیت','text',0],['weight','وزن','number',0],['target_date','موعد','date',0]]},
task:{title:'کار',endpoint:'tasks',fields:[['title','عنوان','text',1],['description','توضیحات','textarea',0],['area_id','حوزه','selectArea',0],['goal_id','هدف','selectGoal',0],['project_id','پروژه','selectProject',0],['milestone_id','Milestone','selectMilestone',0],['status','وضعیت','selectStatus',0],['importance','اهمیت','number',0],['weight','وزن','number',0],['estimated_minutes','زمان برآوردی (دقیقه)','number',0],['deadline','مهلت','datetime-local',0],['planned_start','شروع برنامه','datetime-local',0],['planned_end','پایان برنامه','datetime-local',0],['energy_level','انرژی','number',0],['focus_level','تمرکز','number',0]]},
note:{title:'یادداشت',endpoint:'notes',fields:[['title','عنوان','text',1],['content','متن','textarea',1],['area_id','حوزه','selectArea',0],['goal_id','هدف','selectGoal',0],['project_id','پروژه','selectProject',0],['task_id','کار','selectTask',0]]},
decision:{title:'تصمیم',endpoint:'decisions',fields:[['title','عنوان','text',1],['decision','تصمیم','textarea',1],['rationale','دلیل','textarea',0],['area_id','حوزه','selectArea',0],['decided_at','زمان تصمیم','datetime-local',1]]},
reminder:{title:'یادآور',endpoint:'reminders',fields:[['task_id','کار','selectTask',1],['type','نوع','text',1],['scheduled_at','زمان','datetime-local',1]]},
schedule:{title:'بلوک زمانی',endpoint:'schedule-blocks',fields:[['task_id','کار','selectTask',0],['starts_at','شروع','datetime-local',1],['ends_at','پایان','datetime-local',1],['status','وضعیت','text',0],['source','منبع','text',0]]}
};
function opts(type){const map={selectArea:cache.areas,selectGoal:cache.goals,selectProject:cache.projects,selectMilestone:cache.milestones,selectTask:cache.tasks};return '<select name="__FIELD__"><option value="">—</option>'+map[type].map(x=>'<option value="'+x.id+'">'+esc(x.title||x.name)+'</option>').join('')+'</select>'}
function fieldHtml(f){const [n,l,t,req]=f;if(t.startsWith('select'))return '<div class="field"><label>'+l+'</label>'+opts(t).replace('__FIELD__',n)+'</div>';if(t==='textarea')return '<div class="field full"><label>'+l+'</label><textarea name="'+n+'" '+(req?'required':'')+'></textarea></div>';if(t==='selectStatus')return '<div class="field"><label>'+l+'</label><select name="'+n+'"><option value="inbox">Inbox</option><option value="planned">Planned</option><option value="ready">Ready</option><option value="in_progress">In Progress</option><option value="blocked">Blocked</option><option value="waiting">Waiting</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option><option value="deferred">Deferred</option></select></div>';return '<div class="field"><label>'+l+'</label><input type="'+t+'" name="'+n+'" '+(req?'required':'')+'></div>'}
async function openCreate(kind){await loadCache();if(!kind)kind=view==='tasks'?'task':view==='goals'?'goal':view==='projects'?'project':view==='areas'?'area':view==='milestones'?'milestone':'task';const s=schemas[kind];if(!s)return;showModal(s.title+' جدید','<form id="entityForm"><div class="form-grid">'+s.fields.map(fieldHtml).join('')+'</div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">انصراف</button><button class="btn primary">ذخیره</button></div></form>');$('entityForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e));Object.keys(data).forEach(k=>{if(data[k]==='')data[k]=null});try{await api('/'+s.endpoint,{method:'POST',body:JSON.stringify(data)});closeModal();toast('ذخیره شد');await loadView(view)}catch(x){toast(x.message)}}}
async function editItem(id,kind){const s=schemas[kind];if(!s)return;const item=await api('/'+s.endpoint+'/'+id);showModal('ویرایش '+s.title,'<form id="entityForm"><div class="form-grid">'+s.fields.map(fieldHtml).join('')+'</div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">انصراف</button><button class="btn primary">ذخیره تغییرات</button></div></form>');for(const f of s.fields){const el=document.querySelector('[name="'+f[0]+'"]');if(el&&item[f[0]]!==undefined&&item[f[0]]!==null)el.value=String(item[f[0]]).slice(0,16)===String(item[f[0]])&&f[2]==='datetime-local'?String(item[f[0]]).slice(0,16):item[f[0]]}$('entityForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e));Object.keys(data).forEach(k=>{if(data[k]==='')data[k]=null});try{await api('/'+s.endpoint+'/'+id,{method:'PUT',body:JSON.stringify(data)});closeModal();toast('به‌روزرسانی شد');await loadView(view)}catch(x){toast(x.message)}}}
async function removeItem(id,kind){const s=schemas[kind];if(!s||!confirm('این مورد حذف شود؟'))return;try{await api('/'+s.endpoint+'/'+id,{method:'DELETE'});toast('حذف شد');await loadView(view)}catch(x){toast(x.message)}}
async function openExecution(taskId){showModal('ثبت Execution Log','<form id="entityForm"><div class="form-grid"><div class="field"><label>شروع</label><input name="started_at" type="datetime-local" required></div><div class="field"><label>پایان</label><input name="ended_at" type="datetime-local"></div><div class="field"><label>دقیقه</label><input name="duration_minutes" type="number" min="0"></div><div class="field"><label>تمرکز</label><input name="focus_level" type="number" min="0" max="100"></div><div class="field"><label>انرژی</label><input name="energy_level" type="number" min="0" max="100"></div><div class="field full"><label>نتیجه</label><textarea name="result"></textarea></div><div class="field full"><label>مانع</label><textarea name="blocker"></textarea></div><div class="field full"><label>یادداشت</label><textarea name="notes"></textarea></div></div><div class="modal-actions"><button class="btn">ثبت</button></div></form>');$('entityForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e));try{await api('/tasks/'+taskId+'/execution-logs',{method:'POST',body:JSON.stringify(data)});closeModal();toast('Execution ثبت شد');await loadView('execution')}catch(x){toast(x.message)}}}
async function generateReview(){try{await api('/reviews/generate',{method:'POST',body:JSON.stringify({type:'weekly'})});toast('Review تولید شد');await renderReviews()}catch(e){toast(e.message)}}
function showModal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modal').classList.add('show')}
function closeModal(){$('modal').classList.remove('show');$('modalBody').innerHTML=''}
$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
loadView('today');
</script>
</body></html>